// The decoder half of FoundationStereo's `Feature` (`core/extractor.py`): deconv32_16,
// deconv16_8, deconv8_4 and conv4, against FoundationStereo's own modules in FP64.
//
// Fixtures generated by tests/fixtures/feature_decoder/generate.py (reduced width,
// seeded random weights). Runs on whichever backend teeny-runtime was built for: CUDA,
// or RISC-V under qemu (`--no-default-features --features qemu`, with
// `TEENYC_QEMU_RISCV64=/usr/bin/qemu-riscv64-static` if only the static qemu exists).

#![cfg(any(feature = "cuda", feature = "qemu"))]

mod common;

use common::stereo_block::check_block;
use serial_test::serial;
use vision_rs::models::stereo::feature::decoder::{DecoderDims, decoder};

/// Reduced width (chans [8, 12, 16, 24], 8 ViT channels) on a 64x96 input's maps:
/// x32 2x3 up to x4 16x24. Checks all three returned maps that the decoder computes.
#[test]
#[serial]
fn feature_decoder_matches_pytorch() -> anyhow::Result<()> {
    let dims = DecoderDims {
        chans: [8, 12, 16, 24],
        vit: 8,
    };
    check_block(
        "feature_decoder",
        "feature_decoder",
        &[
            ("x4", &[1, 8, 16, 24]),
            ("x8", &[1, 12, 8, 12]),
            ("x16", &[1, 16, 4, 6]),
            ("x32", &[1, 24, 2, 3]),
            ("vit", &[1, 8, 16, 24]),
        ],
        |i| {
            let [x4, x8, x16, _] = decoder::<f32>(dims, [&i[0], &i[1], &i[2], &i[3]], &i[4]);
            vec![("x4", x4), ("x8", x8), ("x16", x16)]
        },
        1e-5,
    )?;
    Ok(())
}

/// Full width with a real FoundationStereo checkpoint's decoder weights, on the
/// sample left image at 224x320: the backbone maps and the real DINOv2 `vit_feat`
/// (run in FP32 by the generator) in, `Feature`'s `[x4, x8, x16]` out, against FP64.
/// Build the fixtures with tests/fixtures/feature_decoder/gen_real.py, point
/// `FS_REAL_FIXTURES` at the directory holding `feature_real/` and run with
/// `--ignored`.
#[test]
#[serial]
#[ignore = "needs FS_REAL_FIXTURES (real-checkpoint fixtures, not committed)"]
fn feature_decoder_matches_real_checkpoint() -> anyhow::Result<()> {
    let root = std::env::var("FS_REAL_FIXTURES")
        .expect("set FS_REAL_FIXTURES to the real-checkpoint fixture directory");
    let dims = DecoderDims::foundation_stereo();
    let c = dims.chans;
    check_block(
        "feature_real",
        &format!("{root}/feature_real"),
        &[
            ("x4", &[1, c[0], 56, 80]),
            ("x8", &[1, c[1], 28, 40]),
            ("x16", &[1, c[2], 14, 20]),
            ("x32", &[1, c[3], 7, 10]),
            ("vit", &[1, dims.vit, 56, 80]),
        ],
        |i| {
            let [x4, x8, x16, _] = decoder::<f32>(dims, [&i[0], &i[1], &i[2], &i[3]], &i[4]);
            vec![("x4", x4), ("x8", x8), ("x16", x16)]
        },
        1e-4,
    )?;
    Ok(())
}
